import pandas as pd
files = [f"experiment_{i}_csv" for i in range(1,8)]
for f in files:
    try:
        df = pd.read_csv(globals()[f])
        print(f"\n=== {f} ===")
        print(df.columns.tolist())
        if "ProductTiter" in df.columns:
            print("Titer mean:", df["ProductTiter"].mean(), "SD:", df["ProductTiter"].std())
        for c in df.columns:
            if "chel" in c.lower() or "dose" in c.lower() or "additive" in c.lower() or "metal" in c.lower():
                print(c, "values:", df[c].unique())
    except Exception as e:
        print(f"Error on {f}: {e}")
